function ast(text){const f=ts.createSourceFile('case.ts',text,ts.ScriptTarget.Latest,true);const rows=[];function walk(n){if(ts.isCallExpression(n)&&ts.isIdentifier(n.expression)&&n.expression.text==='it'&&n.arguments[0]?.getText(f).includes('R4 real COMMIT first/update/history'))rows.push(n);ts.forEachChild(n,walk)}walk(f);assert.equal(rows.length,1);const n=rows[0],body=n.arguments[1],sites=[];function visit(x){if(ts.isCallExpression(x)&&ts.isPropertyAccessExpression(x.expression)){const s=x.getText(f);if(/^((await )?expect|browserExpect)\(/.test(s)&&/\.(to|not\.)/.test(s))sites.push({line:f.getLineAndCharacterOfPosition(x.getStart(f)).line+1,text:s.replace(/\s+/g,' ')})}ts.forEachChild(x,visit)}visit(body);return {caseText:n.getText(f),sites}}
